// Original, compact teaching material. These are practice questions, not exam PYQs.
const q = (id, prompt, options, answer, explanation) => ({ id, prompt, options, answer, explanation });
export const PACKS = [{id:'ai',title:'AI fundamentals',subtitle:'From agents to neural networks'}, {id:'manufacturing',title:'Manufacturing',subtitle:'From casting to CNC'}];
export const TOPICS = [
 {id:'agents',pack:'ai',title:'Intelligent agents',keywords:['agent','agentic','autonomous','perception','action','goal','environment'],prerequisites:[],minutes:25,
 summary:'An intelligent agent observes its environment, selects an action and uses feedback to move toward a goal. A simple reflex agent follows rules based on the current observation. A goal-based agent considers a desired outcome; a utility-based agent compares how useful different outcomes would be. An agent can be symbolic and rule-based: it does not have to use a language model.',
 example:'A study agent observes your quiz scores, prioritizes a weak topic, schedules practice and checks the next score. A single chatbot reply does not by itself demonstrate this feedback loop.',
 questions:[q('agents-1','Which sequence best describes an agent feedback loop?',['Observe → act → observe the result','Store → display → close','Ask → copy → stop','Always execute the same action'],0,'An agent receives observations, acts and uses the new observations to guide later actions.'),q('agents-2','Which agent explicitly compares the usefulness of different outcomes?',['Simple reflex agent','Utility-based agent','Random agent','A passive database'],1,'A utility-based agent assigns preferences or utilities to outcomes and chooses accordingly.'),q('agents-3','Must an intelligent agent contain a large language model?',['Yes, every agent must','Only if it stores memory','No, symbolic rules and search can also control an agent','Only if it has a user interface'],2,'Classical AI agents can use rules, search and utility functions without a language model.')]},
 {id:'search',pack:'ai',title:'Search & planning',keywords:['search','planning','bfs','dfs','heuristic','astar','a*'],prerequisites:['agents'],minutes:30,
 summary:'Search explores possible states and actions to find a route to a goal. Breadth-first search visits shallower states first and gives a shortest path when every step has equal cost. Depth-first search follows a branch before backtracking. A heuristic estimates the remaining cost. A* ranks states using f(n) = g(n) + h(n), combining cost already paid with estimated cost to the goal.',
 example:'To plan topics, represent prerequisites as a directed graph. Learn the prerequisite before the dependent topic, then choose among available topics using a priority score.',
 questions:[q('search-1','Which search finds a shortest path in an unweighted graph?',['Depth-first search in every case','Breadth-first search','Random search in every case','Greedy search in every case'],1,'BFS explores paths in increasing number of edges, so the first found goal is shortest when edge costs are equal.'),q('search-2','In A*, what is f(n)?',['h(n) − g(n)','Only the number of children','g(n) + h(n)','The final answer'],2,'g is accumulated path cost; h estimates remaining cost.'),q('search-3','A topic depends on a prerequisite. What should the planner normally do?',['Ignore the dependency','Schedule both at random','Remove the topic','Schedule the prerequisite first'],3,'Dependency-aware planning prevents advanced material from being scheduled before its foundations.')]},
 {id:'ml',pack:'ai',title:'Machine learning basics',keywords:['learning','ml','supervised','unsupervised','regression','classification','clustering'],prerequisites:[],minutes:25,
 summary:'Machine learning uses data to fit a model rather than specifying every prediction as a hand-written rule. Supervised learning uses examples with target labels. Classification predicts a category, while regression predicts a numerical value. Unsupervised learning looks for structure without target labels; clustering groups similar examples. Separate training and test data to estimate performance on unseen examples.',
 example:'Predicting whether an email is spam is classification. Predicting a house price is regression. Grouping unlabeled customers by their behavior is clustering.',
 questions:[q('ml-1','Predicting the selling price of a house is usually…',['Classification','Clustering','Regression','Sorting'],2,'Price is a numerical target, so this is a regression problem.'),q('ml-2','Which training data describes supervised learning?',['Examples with target labels','No data','Only random numbers','Examples with no target labels by definition'],0,'Supervised learning fits a relationship between inputs and known targets.'),q('ml-3','Why keep test data separate from training data?',['To make the model larger','To estimate performance on unseen examples','To improve training accuracy automatically','To remove the need for evaluation'],1,'Testing on independent held-out data helps reveal whether the model generalizes.')]},
 {id:'neural',pack:'ai',title:'Neural networks',keywords:['ann','neural','network','forward','backward','backpropagation','gradient','weights'],prerequisites:['ml'],minutes:30,
 summary:'A neuron forms a weighted sum of inputs, adds a bias and applies an activation function. During the forward pass, signals move through layers to produce a prediction. A loss function measures prediction error. Backpropagation applies the chain rule to calculate gradients of that loss. An optimizer uses those gradients to update weights; the learning rate controls the update size.',
 example:'If a model predicts 0.2 for an example whose target is 1, the loss indicates an error. Backpropagation calculates how each weight contributed, and the optimizer adjusts the weights to reduce future error.',
 questions:[q('neural-1','What does a forward pass produce?',['A prediction from the current inputs and weights','A new dataset','Only a learning rate','The final trained model automatically'],0,'The forward pass computes layer outputs and the current prediction.'),q('neural-2','What is the main role of backpropagation?',['Randomly initialize weights','Store images','Calculate loss gradients using the chain rule','Choose the train/test split'],2,'Backpropagation efficiently computes gradients, which an optimizer then uses.'),q('neural-3','What controls the size of an ordinary gradient-descent update?',['Image width alone','Learning rate','Number of file names','Class name'],1,'The learning rate scales the gradient in a weight update.')]},
 {id:'cnn',pack:'ai',title:'CNNs & pooling',keywords:['cnn','convolution','image','pool','pooling','stride','filter','kernel'],prerequisites:['neural'],minutes:30,
 summary:'A convolutional neural network uses learned filters to detect local patterns. A filter slides across the input; stride is how far it moves at each step. Pooling summarizes a neighborhood. Max pooling keeps its largest value, while average pooling uses its mean. For one spatial dimension, output size is floor((N + 2P − K)/S) + 1, with input size N, padding P, kernel K and stride S.',
 example:'For the 2 × 2 patch [1, 3; 2, 4], max pooling returns 4 and average pooling returns 2.5. A 6-wide input with a 2-wide kernel, stride 2 and no padding produces 3 output positions.',
 questions:[q('cnn-1','Max pooling on [1, 3; 2, 4] returns…',['1','2.5','4','10'],2,'Max pooling selects the maximum value in the patch: 4.'),q('cnn-2','A filter has stride 2. What does that mean?',['The filter contains exactly two values','It moves two input positions per step','There are two classes','The output is always 2 × 2'],1,'Stride specifies the step distance of the sliding window.'),q('cnn-3','Average pooling on [2, 4; 6, 8] returns…',['8','20','4','5'],3,'The arithmetic mean is (2 + 4 + 6 + 8)/4 = 5.')]},
 {id:'evaluation',pack:'ai',title:'Model evaluation',keywords:['accuracy','precision','recall','overfitting','evaluation','test','metrics'],prerequisites:['ml'],minutes:25,
 summary:'Accuracy is the fraction of correct predictions. Precision is TP/(TP + FP): of predicted positives, how many are actually positive? Recall is TP/(TP + FN): of actual positives, how many were detected? Accuracy can be misleading when classes are very imbalanced. Overfitting means a model performs well on training examples but generalizes poorly.',
 example:'If a detector predicts 10 positives and 8 are correct, its precision is 8/10 = 0.8. If there were 20 actual positives, recall is 8/20 = 0.4.',
 questions:[q('evaluation-1','Which formula defines precision?',['TP/(TP + FN)','TP/(TP + FP)','FP/(TP + FP)','TN/(TN + FN)'],1,'Precision asks how many predicted positives are correct.'),q('evaluation-2','Very high training accuracy and much lower test accuracy can indicate…',['Perfect generalization','No learning','Overfitting','Guaranteed data quality'],2,'The model may have fitted training-specific patterns that do not generalize.'),q('evaluation-3','There are 8 true positives and 12 false negatives. Recall is…',['0.4','0.8','1.5','0.6'],0,'Recall = TP/(TP + FN) = 8/20 = 0.4.')]},
 {id:'casting',pack:'manufacturing',title:'Casting fundamentals',keywords:['cast','casting','mould','mold','riser','solidification','shrinkage'],prerequisites:[],minutes:25,
 summary:'Casting makes a part by pouring liquid metal into a mould and letting it solidify. A gating system guides the flow. A riser supplies extra liquid metal as the casting shrinks during solidification. A pattern allowance compensates for effects such as shrinkage or later machining. Directional solidification is encouraged so that liquid feeding remains available as solidification progresses.',
 example:'A thick region usually solidifies more slowly than a thin region. Placing an appropriate riser near a region that needs feeding can reduce shrinkage cavities.',
 questions:[q('casting-1','What is the main purpose of a riser?',['Cut the casting','Feed liquid metal to compensate for solidification shrinkage','Measure surface finish','Prevent all gas dissolution'],1,'A riser acts as a reservoir that feeds metal during solidification shrinkage.'),q('casting-2','What does a gating system primarily do?',['Guide molten metal into the mould cavity','Harden the finished tool','Measure cutting force','Rotate the workpiece'],0,'The gating system carries and controls the flow of molten metal into the cavity.'),q('casting-3','A machining allowance provides…',['Extra material for later machining','A larger grain size by definition','Zero shrinkage','Extra lubricant for drilling'],0,'Extra stock is included so machining can produce the required surface and dimensions.')]},
 {id:'forming',pack:'manufacturing',title:'Metal forming',keywords:['forming','forging','rolling','extrusion','drawing','plastic','deformation'],prerequisites:[],minutes:25,
 summary:'Metal forming changes shape mainly through plastic deformation rather than chip removal. Rolling passes metal between rolls. Forging shapes metal using compressive forces. Extrusion pushes material through a die opening, while drawing pulls it through a die. Hot working occurs above the recrystallization temperature; cold working usually increases strength through strain hardening.',
 example:'Wire drawing reduces a wire diameter by pulling it through a die. Extrusion can produce a long section with a constant cross-sectional shape.',
 questions:[q('forming-1','In extrusion, material is usually…',['Pulled through a die','Pushed through a die','Melted in a sand mould','Removed as chips'],1,'Extrusion uses compression to push material through the die opening.'),q('forming-2','Cold working often increases strength because of…',['Strain hardening','Complete melting','Loss of all dislocations','A cutting tool'],0,'Plastic deformation during cold work commonly raises dislocation density and causes strain hardening.'),q('forming-3','Hot working is defined relative to the material’s…',['Boiling temperature','Room temperature only','Recrystallization temperature','Colour'],2,'Hot working occurs above the recrystallization temperature under the relevant processing conditions.')]},
 {id:'machining',pack:'manufacturing',title:'Machining basics',keywords:['machining','turning','milling','drilling','speed','feed','depth'],prerequisites:[],minutes:25,
 summary:'Machining removes material as chips to obtain shape and size. In conventional turning, the workpiece rotates and the tool is fed along it. In milling, a rotating multi-edge cutter removes material. Cutting speed describes relative surface speed, feed describes advancement per revolution or tooth, and depth of cut describes the engaged layer. Their definitions and units depend on the operation.',
 example:'For turning, cutting speed V in m/min equals pi × D × N / 1000 when diameter D is in mm and spindle speed N is in rev/min. Check units before substituting.',
 questions:[q('machining-1','In conventional turning, which normally rotates?',['The workpiece','Only the single-point tool','Neither','The machine base'],0,'A lathe rotates the workpiece while the tool follows a controlled feed motion.'),q('machining-2','For V = pi × D × N / 1000 in m/min, D must be in…',['Metres','Millimetres','Kilometres','Degrees'],1,'The factor 1000 converts the circumference from millimetres to metres.'),q('machining-3','A conventional milling cutter typically has…',['No cutting edges','Only an abrasive liquid','Several cutting edges','A stationary blade only'],2,'Milling uses a rotating cutter with multiple teeth or cutting edges.')]},
 {id:'cutting',pack:'manufacturing',title:'Chip ratio & shear angle',keywords:['chip','cutting','ratio','shear','rake','orthogonal'],prerequisites:['machining'],minutes:30,
 summary:'In orthogonal cutting, chip-thickness ratio r = t1/t2, where t1 is uncut chip thickness and t2 is chip thickness after cutting. Because the chip is usually thicker after deformation, r is usually less than one. The geometric relation is tan(phi) = r cos(alpha)/(1 − r sin(alpha)), where phi is shear angle and alpha is rake angle. Use consistent angle units in calculations.',
 example:'If t1 = 0.2 mm and t2 = 0.5 mm, r = 0.4. This is the chip ratio; its reciprocal, 2.5, is the chip-thickness compression ratio.',
 questions:[q('cutting-1','Uncut thickness is 0.2 mm and chip thickness is 0.5 mm. Chip ratio is…',['2.5','0.4','0.7','0.3'],1,'r = t1/t2 = 0.2/0.5 = 0.4.'),q('cutting-2','In r = t1/t2, t1 is…',['Width of the tool','Thickness after cutting','Uncut chip thickness','Tool life'],2,'t1 represents the thickness of the layer before it deforms into the chip.'),q('cutting-3','With zero rake angle, the geometric relation becomes…',['tan(phi) = r','tan(phi) = 1/r','phi = 0 always','r = 1 always'],0,'Substituting alpha = 0 gives cos(alpha) = 1 and sin(alpha) = 0, so tan(phi) = r.')]},
 {id:'cnc',pack:'manufacturing',title:'CNC programming',keywords:['cnc','gcode','g-code','g90','g91','g01','g00','m06'],prerequisites:['machining'],minutes:30,
 summary:'CNC controls machine motion using programmed instructions. Common ISO-style conventions include G90 for absolute coordinates, G91 for incremental coordinates, G00 for rapid positioning and G01 for linear feed motion. M03 commonly starts the spindle clockwise and M05 stops it. Exact support and behavior depend on the controller; verify its manual before running a machine.',
 example:'In absolute mode, G01 X40 moves toward coordinate X = 40 at the active feed rate. In incremental mode, X40 requests a displacement of +40 in X from the current position.',
 questions:[q('cnc-1','Under common conventions, G90 selects…',['Incremental coordinates','Absolute coordinates','Spindle stop','Tool change'],1,'G90 normally selects absolute positioning, referenced to the active coordinate system.'),q('cnc-2','Under common conventions, G01 requests…',['Rapid positioning','A dwell only','Linear feed motion','Coolant off'],2,'G01 is linear interpolation at the programmed feed rate.'),q('cnc-3','In G91 mode, X10 generally means…',['Go to absolute X = 10','Move +10 along X from the present position','Rotate by 10 degrees','Stop after 10 seconds'],1,'G91 is incremental positioning; the coordinate is interpreted as a relative displacement.')]},
 {id:'metrology',pack:'manufacturing',title:'Limits & fits',keywords:['metrology','limits','fits','tolerance','clearance','interference','measurement'],prerequisites:[],minutes:25,
 summary:'Metrology is the science of measurement. A dimension’s tolerance is the difference between its maximum and minimum permitted values. A clearance fit always leaves space between mating parts at the limiting sizes; an interference fit always has overlap. A transition fit may produce either clearance or interference. Accuracy concerns closeness to a reference value; precision concerns repeatability.',
 example:'If a shaft may measure from 19.98 mm to 20.00 mm, its tolerance is 0.02 mm. If the minimum hole size exceeds the maximum shaft size, clearance is guaranteed.',
 questions:[q('metrology-1','A size ranges from 19.98 to 20.00 mm. Its tolerance is…',['19.99 mm','0.02 mm','0.2 mm','39.98 mm'],1,'Tolerance is upper limit minus lower limit: 20.00 − 19.98 = 0.02 mm.'),q('metrology-2','When minimum hole size exceeds maximum shaft size, the fit is…',['Interference','Transition','Clearance','Impossible'],2,'Even the smallest hole is larger than the largest shaft, so clearance is guaranteed.'),q('metrology-3','Repeatability of measurements primarily describes…',['Precision','A machining allowance','Casting yield','Interference'],0,'Precision describes agreement among repeated measurements. Accuracy concerns closeness to the reference.')]}
];
export const topicById = id => TOPICS.find(t => t.id === id);
